  1	# Replaces the image's main config. Serves the built SPA and proxies /api/ to the API replicas.
  2	# Directive reference: https://nginx.org/en/docs/dirindex.html
  3	
  4	# Pinned, because "auto" starts one worker per CPU and each worker keeps its own idle upstream connections.
  5	worker_processes 2;
  6	# Room for both workers' connections, two per proxied request, whatever limit the host sets.
  7	worker_rlimit_nofile 8192;
  8	# The unprivileged image can write only to /tmp.
  9	pid /tmp/nginx.pid;
 10	error_log /dev/stderr warn;
 11	
 12	# Each proxied request holds two connections: one to the browser, one to the API.
 13	events {
 14	    worker_connections 4096;
 15	}
 16	
 17	http {
 18	    include mime.types;
 19	    access_log /dev/stdout;
 20	
 21	    client_body_temp_path /tmp/client_temp;
 22	    proxy_temp_path /tmp/proxy_temp;
 23	    fastcgi_temp_path /tmp/fastcgi_temp;
 24	    uwsgi_temp_path /tmp/uwsgi_temp;
 25	    scgi_temp_path /tmp/scgi_temp;
 26	
 27	    gzip on;
 28	    gzip_types text/css application/javascript text/javascript application/json;
 29	
 30	    # Docker's embedded DNS. A short validity picks up replicas whose addresses change.
 31	    resolver 127.0.0.11 valid=10s ipv6=off;
 32	
 33	    # Pass on the caller's request id, or make one, so nginx and the API log the same id.
 34	    map $http_x_request_id $req_id {
 35	        default $http_x_request_id;
 36	        "" $request_id;
 37	    }
 38	
 39	    # Swagger UI at /api/docs loads its script and stylesheet from jsDelivr, its icon from fastapi.tiangolo.com,
 40	    # and starts from one inline script allowed by its hash; the hash changes when FastAPI changes that script.
 41	    map $uri $csp {
 42	        default "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'";
 43	        /api/docs "default-src 'self'; script-src 'self' https://cdn.jsdelivr.net 'sha256-eV3QMumkWxytVHa/LDvu+mnW+PcSAEI4SfFu0iIlbDc='; style-src 'self' https://cdn.jsdelivr.net; img-src 'self' data: https://fastapi.tiangolo.com; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'";
 44	    }
 45	
 46	    upstream api {
 47	        # "resolve" re-reads the replicas' addresses from DNS; it needs a shared zone.
 48	        # https://nginx.org/en/docs/http/ngx_http_upstream_module.html#resolve
 49	        zone api 64k;
 50	        server api:8000 resolve;
 51	        # At most 16 idle connections per worker, 32 in all, well under each replica's 200-connection limit.
 52	        # https://nginx.org/en/docs/http/ngx_http_upstream_module.html#keepalive
 53	        keepalive 16;
 54	        # Shorter than uvicorn's 75 s, so nginx never reuses a connection the API is closing.
 55	        keepalive_timeout 60s;
 56	    }
 57	
 58	    server {
 59	        listen 8080;
 60	        root /usr/share/nginx/html;
 61	        server_tokens off;
 62	        client_max_body_size 64k;
 63	
 64	        # Every response carries these; a location's own headers are added to them, not swapped for them.
 65	        # https://nginx.org/en/docs/http/ngx_http_headers_module.html#add_header_inherit
 66	        add_header_inherit merge;
 67	        add_header Content-Security-Policy $csp always;
 68	        add_header X-Content-Type-Options nosniff always;
 69	        add_header Referrer-Policy strict-origin-when-cross-origin always;
 70	        add_header X-Frame-Options DENY always;
 71	        add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
 72	        add_header Cross-Origin-Opener-Policy same-origin always;
 73	
 74	        # The health probes are for Docker and Kubernetes only, never the public front door.
 75	        location = /livez {
 76	            return 404;
 77	        }
 78	        location = /readyz {
 79	            return 404;
 80	        }
 81	
 82	        # Since nginx 1.29.7 the proxy speaks HTTP/1.1 and sends no Connection header by default,
 83	        # which upstream keep-alive needs. https://nginx.org/en/CHANGES-1.30
 84	        location /api/ {
 85	            proxy_pass http://api;
 86	            proxy_set_header Host $host;
 87	            proxy_set_header X-Request-ID $req_id;
 88	            proxy_read_timeout 30s;
 89	        }
 90	
 91	        # Vite puts a content hash in every asset's name, so a file never changes under its URL.
 92	        # Cache-Control has no "always", so a missing asset's 404 is never cached for a year.
 93	        location /assets/ {
 94	            add_header Cache-Control "public, max-age=31536000, immutable";
 95	        }
 96	
 97	        # Any other path is a client-side route: serve index.html, and have the browser revalidate it every time.
 98	        location / {
 99	            try_files $uri /index.html;
100	            add_header Cache-Control "no-cache";
101	        }
102	    }
103	}

