 1	import { addTask, expect, signOut, signUp, taskList, taskTitles, test } from "./fixtures.ts";
 2	
 3	test("signs up, signs out, signs back in, and a second account sees none of the first account's tasks", async ({
 4	  page,
 5	}) => {
 6	  const first = await signUp(page);
 7	  await addTask(page, "Renew the passport");
 8	  await signOut(page);
 9	
10	  await page.getByLabel("Email").fill(first.email);
11	  await page.getByLabel("Password").fill(first.password);
12	  await page.getByRole("button", { name: "Sign in" }).click();
13	  await expect(taskTitles(page)).toHaveText(["Renew the passport"]);
14	
15	  await signOut(page);
16	  await signUp(page);
17	  await expect(page.getByText("No tasks yet")).toBeVisible();
18	  await expect(taskList(page)).toHaveCount(0);
19	});
 1	import { addTask, expect, signUp, taskTitles, test } from "./fixtures.ts";
 2	
 3	// A date in next year, so the screen spells it with its year whatever day the suite runs.
 4	const nextYear = new Date().getUTCFullYear() + 1;
 5	const dueDate = `${String(nextYear)}-03-14`;
 6	const dueText = `Due ${new Intl.DateTimeFormat("en-US", {
 7	  weekday: "short",
 8	  month: "short",
 9	  day: "numeric",
10	  year: "numeric",
11	  timeZone: "UTC",
12	}).format(new Date(`${dueDate}T00:00:00Z`))}`;
13	
14	test("creates a task, edits every field on the detail screen and completes it", async ({
15	  page,
16	}) => {
17	  await signUp(page);
18	  await addTask(page, "Draft the talk");
19	  await taskTitles(page).filter({ hasText: "Draft the talk" }).click();
20	  await expect(page.getByRole("heading", { level: 1, name: "Draft the talk" })).toBeVisible();
21	
22	  await page.getByRole("button", { name: "Edit task" }).click();
23	  await page.getByLabel("Title").fill("Rehearse the talk");
24	  await page.getByLabel("Due date").fill(dueDate);
25	  await page.getByLabel("Notes").fill("Twice through, once with a timer.");
26	  await page.getByRole("button", { name: "Save changes" }).click();
27	
28	  await expect(page.getByRole("heading", { level: 1, name: "Rehearse the talk" })).toBeVisible();
29	  await expect(page.getByText(dueText)).toBeVisible();
30	  await expect(page.getByText("Twice through, once with a timer.")).toBeVisible();
31	
32	  const completed = page.getByRole("checkbox", { name: "Completed: Rehearse the talk" });
33	  // `check()` insists the box flips during the click; the app flips it a moment later, once the update is queued.
34	  await completed.click();
35	  await expect(completed).toBeChecked();
36	  await expect(page.getByText("Done", { exact: true })).toBeVisible();
37	
38	  await page.getByRole("link", { name: "All tasks" }).click();
39	  await expect(taskTitles(page)).toHaveText(["Rehearse the talk"]);
40	  await expect(page.getByRole("checkbox", { name: "Completed: Rehearse the talk" })).toBeChecked();
41	});
 1	import { addTasks, expect, signOut, signUp, taskTitles, test } from "./fixtures.ts";
 2	
 3	test("deletes a task after confirming and signs out", async ({ page }) => {
 4	  await signUp(page);
 5	  await addTasks(page, ["Book the dentist", "Return the library books"]);
 6	  await taskTitles(page).filter({ hasText: "Book the dentist" }).click();
 7	
 8	  await page.getByRole("button", { name: "Delete" }).click();
 9	  const confirm = page.getByRole("group", {
10	    name: "Delete “Book the dentist”? This can't be undone.",
11	  });
12	  await confirm.getByRole("button", { name: "Delete task" }).click();
13	
14	  await expect(page.getByRole("heading", { level: 1, name: "Tasks" })).toBeVisible();
15	  await expect(taskTitles(page)).toHaveText(["Return the library books"]);
16	  await page.reload();
17	  await expect(taskTitles(page)).toHaveText(["Return the library books"]);
18	
19	  await signOut(page);
20	  await page.goto("/tasks");
21	  await expect(page.getByRole("heading", { level: 1, name: "Sign in" })).toBeVisible();
22	});
 1	import {
 2	  addTasks,
 3	  centreOf,
 4	  dragAnnouncement,
 5	  expect,
 6	  moveHandle,
 7	  signUp,
 8	  taskList,
 9	  taskRow,
10	  taskTitles,
11	  test,
12	} from "./fixtures.ts";
13	
14	test("reorders by keyboard and by mouse, then finds a task by search with reorder turned off", async ({
15	  page,
16	}) => {
17	  await signUp(page);
18	  await addTasks(page, ["Water the plants", "Call the bank", "Pay the rent"]);
19	  await expect(taskTitles(page)).toHaveText(["Pay the rent", "Call the bank", "Water the plants"]);
20	
21	  // Space picks the task up, each arrow moves it one place, and Space drops it.
22	  await moveHandle(page, "Pay the rent").focus();
23	  await page.keyboard.press("Space");
24	  await expect(dragAnnouncement(page, "Pay the rent")).toHaveCount(1);
25	  // The list drops arrow keys until it has measured the rows after the pickup, so the first move is pressed again
26	  // until it lands: https://playwright.dev/docs/test-assertions#expecttopass
27	  await expect(async () => {
28	    await page.keyboard.press("ArrowDown");
29	    await expect(dragAnnouncement(page, "Pay the rent is now at position 2 of 3.")).toHaveCount(1, {
30	      timeout: 1000,
31	    });
32	  }).toPass();
33	  await page.keyboard.press("ArrowDown");
34	  await expect(dragAnnouncement(page, "Pay the rent is now at position 3 of 3.")).toHaveCount(1);
35	  await page.keyboard.press("Space");
36	  await expect(taskTitles(page)).toHaveText(["Call the bank", "Water the plants", "Pay the rent"]);
37	
38	  // The list only starts a mouse drag after the pointer travels a few pixels, so move in steps.
39	  const from = await centreOf(moveHandle(page, "Water the plants"));
40	  const to = await centreOf(taskRow(page, "Call the bank"));
41	  await page.mouse.move(from.x, from.y);
42	  await page.mouse.down();
43	  await page.mouse.move(from.x, to.y, { steps: 10 });
44	  await page.mouse.up();
45	  await expect(taskTitles(page)).toHaveText(["Water the plants", "Call the bank", "Pay the rent"]);
46	
47	  await page.reload();
48	  await expect(taskTitles(page)).toHaveText(["Water the plants", "Call the bank", "Pay the rent"]);
49	
50	  await page.getByRole("searchbox", { name: "Search tasks" }).fill("bank");
51	  await expect(
52	    page.getByText("1 match for “bank”. Reordering is off while you search."),
53	  ).toBeVisible();
54	  await expect(taskTitles(page)).toHaveText(["Call the bank"]);
55	  await expect(taskList(page).getByRole("button", { name: /^Move / })).toHaveCount(0);
56	});
 1	import type { Page } from "@playwright/test";
 2	import {
 3	  type Point,
 4	  addTasks,
 5	  centreOf,
 6	  dragAnnouncement,
 7	  expect,
 8	  moveHandle,
 9	  scrollsSideways,
10	  signUp,
11	  taskRow,
12	  taskTitles,
13	  test,
14	} from "./fixtures.ts";
15	
16	test.use({ viewport: { width: 375, height: 812 }, hasTouch: true });
17	
18	// Playwright's touchscreen only taps, so a press-and-drag goes through Chromium's own input events:
19	// https://chromedevtools.github.io/devtools-protocol/tot/Input/#method-dispatchTouchEvent
20	const dragByTouch = async (page: Page, title: string, from: Point, to: Point): Promise<void> => {
21	  const cdp = await page.context().newCDPSession(page);
22	  await cdp.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: [from] });
23	  // The list picks a task up only after a short press, and announces it to screen readers when it does.
24	  await expect(dragAnnouncement(page, title)).toHaveCount(1);
25	  const steps = 10;
26	  for (let step = 1; step <= steps; step += 1) {
27	    const share = step / steps;
28	    await cdp.send("Input.dispatchTouchEvent", {
29	      type: "touchMove",
30	      touchPoints: [{ x: from.x + (to.x - from.x) * share, y: from.y + (to.y - from.y) * share }],
31	    });
32	  }
33	  await cdp.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
34	  await cdp.detach();
35	};
36	
37	test("runs create, reorder by touch and delete at 375 px with no horizontal scroll", async ({
38	  page,
39	}) => {
40	  await signUp(page);
41	  await addTasks(page, ["Buy stamps", "Post the parcel"]);
42	  await expect(taskTitles(page)).toHaveText(["Post the parcel", "Buy stamps"]);
43	  expect(await scrollsSideways(page)).toBe(false);
44	
45	  await dragByTouch(
46	    page,
47	    "Buy stamps",
48	    await centreOf(moveHandle(page, "Buy stamps")),
49	    await centreOf(taskRow(page, "Post the parcel")),
50	  );
51	  await expect(taskTitles(page)).toHaveText(["Buy stamps", "Post the parcel"]);
52	  await page.reload();
53	  await expect(taskTitles(page)).toHaveText(["Buy stamps", "Post the parcel"]);
54	
55	  await taskTitles(page).filter({ hasText: "Post the parcel" }).tap();
56	  await expect(page.getByRole("heading", { level: 1, name: "Post the parcel" })).toBeVisible();
57	  expect(await scrollsSideways(page)).toBe(false);
58	  await page.getByRole("button", { name: "Delete" }).tap();
59	  await page.getByRole("button", { name: "Delete task" }).tap();
60	
61	  await expect(taskTitles(page)).toHaveText(["Buy stamps"]);
62	  expect(await scrollsSideways(page)).toBe(false);
63	});

