  1	import { randomUUID } from "node:crypto";
  2	import {
  3	  type ConsoleMessage,
  4	  type Locator,
  5	  type Page,
  6	  test as base,
  7	  expect,
  8	} from "@playwright/test";
  9	
 10	declare global {
 11	  interface Window {
 12	    /** Set by the fixture through `page.exposeFunction`; reports a blocked resource back to the test. */
 13	    reportCspViolation?: (report: string) => Promise<void>;
 14	  }
 15	}
 16	
 17	/** An account a test signed up, so it can sign back in. */
 18	export interface Account {
 19	  readonly email: string;
 20	  readonly password: string;
 21	}
 22	
 23	// Chromium logs each failed response itself; a 401 from the API is an answer the app expects (a visitor), not a fault.
 24	const isExpectedApiAnswer = (message: ConsoleMessage): boolean =>
 25	  message.text().startsWith("Failed to load resource: the server responded with a status of 401") &&
 26	  new URL(message.location().url, "http://localhost").pathname.startsWith("/api/");
 27	
 28	/**
 29	 * Playwright's test, with a page that fails the test on any `console.error`, uncaught exception or CSP violation.
 30	 * Those are what only a real browser against the real stack shows, such as the nginx CSP blocking an inline style.
 31	 */
 32	export const test = base.extend({
 33	  page: async ({ page }, use) => {
 34	    const problems: string[] = [];
 35	    page.on("console", (message) => {
 36	      if (message.type() === "error" && !isExpectedApiAnswer(message))
 37	        problems.push(`console.error: ${message.text()}`);
 38	    });
 39	    page.on("pageerror", (error) => {
 40	      problems.push(`uncaught: ${error.message}`);
 41	    });
 42	    // Init scripts and exposed functions run outside the page's CSP: https://playwright.dev/docs/api/class-page#page-add-init-script
 43	    await page.exposeFunction("reportCspViolation", (report: string) => {
 44	      problems.push(`CSP violation: ${report}`);
 45	    });
 46	    await page.addInitScript(() => {
 47	      document.addEventListener("securitypolicyviolation", (event) => {
 48	        void window.reportCspViolation?.(
 49	          `${event.effectiveDirective} blocked ${event.blockedURI || "inline"} in ${event.sourceFile}:${String(event.lineNumber)}`,
 50	        );
 51	      });
 52	    });
 53	    await use(page);
 54	    expect(problems, "the browser reported errors").toEqual([]);
 55	  },
 56	});
 57	
 58	export { expect };
 59	
 60	/** A fresh account for one test: a unique address on the reserved example.com domain. */
 61	export const newAccount = (): Account => ({
 62	  email: `e2e-${randomUUID()}@example.com`,
 63	  password: "browser-journey-password",
 64	});
 65	
 66	/** Create an account through the sign-up screen and wait for the task list it lands on. */
 67	export const signUp = async (page: Page, account: Account = newAccount()): Promise<Account> => {
 68	  await page.goto("/sign-up");
 69	  await page.getByLabel("Email").fill(account.email);
 70	  await page.getByLabel("Password").fill(account.password);
 71	  await page.getByRole("button", { name: "Create account" }).click();
 72	  await expect(page.getByRole("heading", { level: 1, name: "Tasks" })).toBeVisible();
 73	  return account;
 74	};
 75	
 76	/** Sign out from the masthead and wait for the sign-in screen. */
 77	export const signOut = async (page: Page): Promise<void> => {
 78	  await page.getByRole("button", { name: "Sign out" }).click();
 79	  await expect(page.getByRole("heading", { level: 1, name: "Sign in" })).toBeVisible();
 80	};
 81	
 82	/** The ruled list of tasks on the task list screen. */
 83	export const taskList = (page: Page): Locator => page.getByRole("list", { name: "Tasks" });
 84	
 85	/** Each task's title link in the list, top to bottom: what the user reads as the order. */
 86	export const taskTitles = (page: Page): Locator => taskList(page).getByRole("link");
 87	
 88	/** Add a task with the quick-add form and wait until the server's row replaces the pending one. */
 89	export const addTask = async (page: Page, title: string): Promise<void> => {
 90	  await page.getByRole("textbox", { name: "New task" }).fill(title);
 91	  await page.getByRole("button", { name: "Add task" }).click();
 92	  await expect(taskTitles(page).filter({ hasText: title })).toBeVisible();
 93	  await expect(page.getByRole("button", { name: "Add task" })).toBeEnabled();
 94	};
 95	
 96	/** Add tasks in order. New tasks go to the top, so the list shows them in reverse. */
 97	export const addTasks = async (page: Page, titles: readonly string[]): Promise<void> => {
 98	  for (const title of titles) await addTask(page, title);
 99	};
100	
101	/** The handle that reorders a task by keyboard, mouse or touch. */
102	export const moveHandle = (page: Page, title: string): Locator =>
103	  page.getByRole("button", { name: `Move ${title}` });
104	
105	/** The list row that holds a task. */
106	export const taskRow = (page: Page, title: string): Locator =>
107	  taskList(page).getByRole("listitem").filter({ hasText: title });
108	
109	/** A point on the screen, in CSS pixels from the viewport's top left. */
110	export interface Point {
111	  readonly x: number;
112	  readonly y: number;
113	}
114	
115	/** The centre of an element on screen; fails the test when the element has no box. */
116	export const centreOf = async (locator: Locator): Promise<Point> => {
117	  const box = await locator.boundingBox();
118	  if (box === null) throw new Error(`${locator.toString()} is not on screen`);
119	  return { x: box.x + box.width / 2, y: box.y + box.height / 2 };
120	};
121	
122	/**
123	 * What the list last told screen readers about a carried task. Before anything is picked up, no announcement names a
124	 * task, so a match means the drag has started.
125	 */
126	export const dragAnnouncement = (page: Page, text: string): Locator =>
127	  page.getByRole("status").filter({ hasText: text });
128	
129	/** True when the page is wider than the viewport, which would make the user scroll sideways. */
130	export const scrollsSideways = (page: Page): Promise<boolean> =>
131	  page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth);
