  1	// The load test: every virtual user (VU) signs in once, seeds five tasks, then repeats a full task journey.
  2	// Run through compose: `docker compose --profile load run --rm k6 run /scripts/journey.js`.
  3	// k6 scripting reference: https://grafana.com/docs/k6/latest/javascript-api/
  4	
  5	import exec from "k6/execution";
  6	import http from "k6/http";
  7	import { check, sleep } from "k6";
  8	import { Counter } from "k6/metrics";
  9	
 10	const BASE_URL = __ENV.BASE_URL || "http://web:8080";
 11	const APP_ORIGIN = __ENV.APP_ORIGIN || "http://localhost:8080";
 12	const VUS = Number(__ENV.VUS || 200);
 13	const HOLD = __ENV.HOLD || "3m";
 14	const RESULTS_DIR = __ENV.RESULTS_DIR || "/results";
