  1	"""Find the round's capacity: run the k6 journey at rising user counts until a budget fails.
  2	
  3	Each step starts from a fresh stack, so earlier steps' accounts and tasks never slow a later one.
  4	The capacity figure is the last step whose budgets all held. Results go to load/results/<UTC>-<sha>/.
  5	
  6	Usage, from the repo root: python3 load/run_stepped.py [--steps 200,400,600,800,1000] [--hold 2m]
  7	"""
  8	
  9	from __future__ import annotations
 10	
 11	import argparse
 12	import json
 13	import logging
 14	import os
 15	import subprocess
 16	import sys
 17	from datetime import datetime, timezone
 18	from pathlib import Path
 19	
 20	ROOT = Path(__file__).resolve().parent.parent
 21	RESULTS = ROOT / "load" / "results"
 22	log = logging.getLogger("run_stepped")
 23	
 24	
 25	def output(*command: str) -> str:
 26	    """Run a command and return its trimmed standard output."""
 27	    return subprocess.run(command, cwd=ROOT, check=True, capture_output=True, text=True).stdout.strip()
 28	
 29	
 30	def machine() -> dict[str, str]:
 31	    """Describe the Mac and Docker's share of it; nothing that identifies the machine, such as a serial number."""
 32	    model, cpu, cores, memory = output(
 33	        "sysctl", "-n", "hw.model", "machdep.cpu.brand_string", "hw.ncpu", "hw.memsize"
 34	    ).splitlines()
 35	    docker_cpus, docker_memory = output("docker", "info", "--format", "{{.NCPU}} {{.MemTotal}}").split()
 36	    return {
 37	        "model": model,
 38	        "cpu": cpu,
 39	        "cores": cores,
 40	        "memory_gib": f"{int(memory) / 2**30:.0f}",
 41	        "docker_cpus": docker_cpus,
 42	        "docker_memory_gib": f"{int(docker_memory) / 2**30:.1f}",
 43	    }
 44	
 45	
 46	def fresh_stack(sha: str) -> None:
 47	    """Remove the stack and its database volume, then build and start it again."""
 48	    subprocess.run(["docker", "compose", "down", "-v"], cwd=ROOT, check=True)
 49	    subprocess.run(
 50	        ["docker", "compose", "up", "--build", "--wait"], cwd=ROOT, check=True, env={**os.environ, "GIT_SHA": sha}
 51	    )
 52	
 53	
 54	def run_step(vus: int, hold: str, results_dir: str, sha: str) -> bool:
 55	    """Run the journey at `vus` users; True when k6 exits 0, which means every budget held."""
 56	    settings = [f"VUS={vus}", f"HOLD={hold}", f"RESULTS_DIR=/results/{results_dir}"]
 57	    command = [
 58	        *["docker", "compose", "--profile", "load", "run", "--rm"],
 59	        *(part for setting in settings for part in ("-e", setting)),
 60	        *["k6", "run", "/scripts/journey.js"],
 61	    ]
 62	    # The same GIT_SHA as the stack, or compose would resolve other image tags and recreate the stack under test.
 63	    return subprocess.run(command, cwd=ROOT, env={**os.environ, "GIT_SHA": sha}).returncode == 0
 64	
 65	
 66	def main() -> int:
 67	    """Run each step in order, stop at the first that misses a budget, and record the capacity."""
 68	    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
 69	    parser.add_argument("--steps", default="200,400,600,800,1000", help="comma-separated user counts, in order")
 70	    parser.add_argument("--hold", default="2m", help="how long each step holds its full user count")
 71	    args = parser.parse_args()
 72	    logging.basicConfig(level=logging.INFO, format="== %(message)s")
 73	    steps = [int(step) for step in args.steps.split(",")]
 74	
 75	    sha = output("git", "rev-parse", "--short", "HEAD")
 76	    run_name = f"{datetime.now(timezone.utc):%Y%m%dT%H%M%SZ}-{sha}"
 77	    run_dir = RESULTS / run_name
 78	    run_dir.mkdir(parents=True)
 79	    (run_dir / "machine.json").write_text(json.dumps(machine(), indent=2) + "\n")
 80	
 81	    outcomes: list[dict[str, object]] = []
 82	    for vus in steps:
 83	        log.info("step: %s users, hold %s", vus, args.hold)
 84	        fresh_stack(sha)
 85	        passed = run_step(vus, args.hold, run_name, sha)
 86	        outcomes.append({"vus": vus, "passed": passed})
 87	        if not passed:
 88	            break
 89	
 90	    passed_steps = [outcome["vus"] for outcome in outcomes if outcome["passed"]]
 91	    capacity = {
 92	        "capacity_vus": passed_steps[-1] if passed_steps else None,
 93	        "hold": args.hold,
 94	        "sha": sha,
 95	        "steps": outcomes,
 96	    }
 97	    (run_dir / "capacity.json").write_text(json.dumps(capacity, indent=2) + "\n")
 98	    log.info("capacity: %s users; results in %s", capacity["capacity_vus"], run_dir.relative_to(ROOT))
 99	    return 0
100	
101	
102	if __name__ == "__main__":
103	    sys.exit(main())

